import Foundation

/// 미니룸 manifest (Vaultly/Rooms/rooms.json, generated by scripts/draw_rooms.py): one room per tier, furniture placed in
/// a 200×150 pixel canvas, each piece unlocked at a progress point toward the next tier or shown only when "poor".
struct RoomManifest: Decodable {
    struct Prop: Decodable, Identifiable, Equatable {
        let name: String
        let x: Int, y: Int, w: Int, h: Int
        let unlock: Double
        let when: String            // "always" | "poor"
        var id: String { name }
        var bottom: Int { y + h }
        var isClutter: Bool { when == "poor" }
    }
    struct Tier: Decodable {
        let bg: String
        let name: String
        let anchor: [Int]           // character feet (x, y)
        let scale: Double           // sprite scale relative to room pixels
        let props: [Prop]
    }
    let canvas: [Int]
    let wallBottom: Int
    let tiers: [String: Tier]

    static func load(_ data: Data) throws -> RoomManifest { try JSONDecoder().decode(RoomManifest.self, from: data) }
}

final class RoomAssets {
    static let shared = RoomAssets()
    let manifest: RoomManifest?
    private init() {
        manifest = Bundle.main.url(forResource: "rooms", withExtension: "json")
            .flatMap { try? Data(contentsOf: $0) }
            .flatMap { try? RoomManifest.load($0) }
    }
}

/// What the room shows for a given wealth: the tier's room, furniture unlocked by progress toward the next tier,
/// and clutter (bills, bottles) when the account is empty or in debt.
struct RoomState: Equatable {
    let tier: WealthTier
    let progress: Double        // 0…1 toward the next tier (재벌: toward 10× its threshold)
    let poor: Bool

    static let brokeGoal: Decimal = 5_000_000   // 거지 → 서민 has no net-worth threshold; 5백만원 saved = "moving out"

    static func progress(netWorth: Decimal, tier: WealthTier) -> Double {
        var goal: Decimal
        if let next = GameState.nextTier(after: tier) { goal = GameState.threshold(for: next) } else { goal = GameState.threshold(for: .tycoon) * 10 }
        if goal <= 0 { goal = brokeGoal }
        return min(1, max(0, (netWorth / goal).doubleValue))
    }

    func visible(_ props: [RoomManifest.Prop]) -> [RoomManifest.Prop] {
        props.filter { $0.isClutter ? poor : $0.unlock <= progress + 1e-9 }
    }

    /// "다음 방까지" — the room you move into at the next tier.
    var nextTier: WealthTier? { GameState.nextTier(after: tier) }
}
